"use client";

import Link from "next/link";

import { Plus, Search, Cpu, Radio, Activity, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

import { Trash2, Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { deleteSmartMeter, getAllSmartMeters } from "@/lib/api/smartmeter";

export default function SmartMeterPage() {
  const [searchTerm, setSearchTerm] = useState("");
  const [deleting, setDeleting] = useState<string | null>(null);
  const { toast } = useToast();
  useEffect(() => {
    loadSmartMeters();
  }, []);

  async function loadSmartMeters() {
    setLoading(true);

    const result = await getAllSmartMeters();

    if (result.success) {
      setSmartMeters(result.data || []);
    }

    setLoading(false);
  }
  const [smartMeters, setSmartMeters] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const filteredMeters = smartMeters.filter((meter) =>
    meter.smartMeterId.toLowerCase().includes(searchTerm.toLowerCase()),
  );

  const totalSensors = smartMeters.reduce(
    (sum, meter) => sum + (meter.sensors?.length || 0),
    0,
  );

  const totalConverters = smartMeters.reduce(
    (sum, meter) => sum + (meter.mediaConverters?.length || 0),
    0,
  );

  if (loading) {
    return (
      <div className="p-8 text-center text-gray-400">
        Loading Smart Meters...
      </div>
    );
  }

  const handleDelete = async (id: string, smartMeterId: string) => {
    setDeleting(id);

    try {
      const response = await deleteSmartMeter(id);

      if (response.success) {
        setSmartMeters((prev) => prev.filter((m) => m.id !== id));

        toast({
          title: "Success",
          description: `Smart Meter "${smartMeterId}" deleted successfully`,
        });
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to delete Smart Meter",
          variant: "destructive",
        });
      }
    } finally {
      setDeleting(null);
    }
  };

  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white md:text-3xl">
              Smart Meter Management
            </h1>
            <p className="mt-1 text-sm text-gray-400">
              Manage and monitor smart meter hubs
            </p>
          </div>

          <Link href="/smartmeter/add">
            <Button className="gap-2 bg-[#8B0000] hover:bg-[#6B0000]">
              <Plus className="h-4 w-4" />
              Add Smart Meter
            </Button>
          </Link>
        </div>

        {/* Stats */}
        <div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Cpu className="h-5 w-5 text-blue-400" />
              <span className="text-sm text-gray-400">Smart Meters</span>
            </div>
            <p className="mt-2 text-3xl font-bold text-white">
              {smartMeters.length}
            </p>
          </div>

          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Activity className="h-5 w-5 text-green-400" />
              <span className="text-sm text-gray-400">Active</span>
            </div>
            <p className="mt-2 text-3xl font-bold text-green-400">
              {smartMeters.filter((m) => m.status === "Active").length}
            </p>
          </div>

          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Radio className="h-5 w-5 text-blue-400" />
              <span className="text-sm text-gray-400">Connected Devices</span>
            </div>
            <p className="mt-2 text-3xl font-bold text-blue-400">
              {totalSensors}
            </p>
          </div>

          <div className="rounded-lg border border-[#333] bg-[#222] p-4">
            <div className="flex items-center gap-2">
              <Cpu className="h-5 w-5 text-yellow-400" />
              <span className="text-sm text-gray-400">Media Converters</span>
            </div>
            <p className="mt-2 text-3xl font-bold text-yellow-400">
              {totalConverters}
            </p>
          </div>
        </div>

        {/* Search */}
        <div className="mb-6">
          <div className="relative max-w-sm">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
            <Input
              placeholder="Search smart meters..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="border-[#333] bg-[#222] pl-10 text-white placeholder:text-gray-500"
            />
          </div>
        </div>

        {/* Cards */}
        <div className="grid gap-5 lg:grid-cols-2">
          {filteredMeters.map((meter) => {
            const faults: string[] = [];

            meter.mediaConverters?.forEach((mc) => {
              if (!mc.fx)
                faults.push(`${mc.mediaConverterId} → Fiber input signal lost`);

              if (!mc.tx)
                faults.push(
                  `${mc.mediaConverterId} → Data transmission stopped`,
                );

              if (!mc.link)
                faults.push(
                  `${mc.mediaConverterId} → Network link disconnected`,
                );

              if (!mc.pwr)
                faults.push(`${mc.mediaConverterId} → Power failure`);

              if (!mc.act)
                faults.push(`${mc.mediaConverterId} → No activity detected`);

              if (!mc.fdx)
                faults.push(`${mc.mediaConverterId} → Half duplex mode`);
            });

            return (
              <div
                key={meter.id}
                className="
          rounded-xl
          border border-[#333]
          bg-gradient-to-b
          from-[#232323]
          to-[#181818]
          p-5
          shadow-2xl
          transition-all
          duration-300
          hover:border-[#555]
          hover:shadow-green-500/10
        "
              >
                {/* Header */}
                <div className="mb-4 flex items-center justify-between border-b border-[#333] pb-3">
                  <div>
                    <p className="text-[10px] tracking-[0.3em] text-gray-500">
                      SMART METER
                    </p>

                    <h3 className="mt-1 text-lg font-bold text-white">
                      {meter.smartMeterId}
                    </h3>
                  </div>

                  <div className="flex items-center gap-3">
                    <button
                      onClick={() => handleDelete(meter.id, meter.smartMeterId)}
                      disabled={deleting === meter.id}
                      className="
      rounded-lg
      border border-red-500/20
      bg-red-500/10
      p-2
      text-red-400
      transition
      hover:bg-red-500/20
      hover:text-red-300
    "
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>

                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-gray-400 hover:bg-red-600/20 hover:text-red-400"
                          disabled={deleting === meter.id}
                        >
                          {deleting === meter.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <Trash2 className="h-4 w-4" />
                          )}
                        </Button>
                      </AlertDialogTrigger>

                      <AlertDialogContent className="border-[#333] bg-[#222]">
                        <AlertDialogHeader>
                          <AlertDialogTitle className="text-white">
                            Delete Smart Meter
                          </AlertDialogTitle>

                          <AlertDialogDescription className="text-gray-400">
                            Are you sure you want to delete "
                            {meter.smartMeterId}"? This action cannot be undone
                            and will also remove all connected Media Converters.
                          </AlertDialogDescription>
                        </AlertDialogHeader>

                        <AlertDialogFooter>
                          <AlertDialogCancel className="border-[#333] bg-transparent text-white hover:bg-[#333]">
                            Cancel
                          </AlertDialogCancel>

                          <AlertDialogAction
                            onClick={() =>
                              handleDelete(meter.id, meter.smartMeterId)
                            }
                            className="bg-red-600 text-white hover:bg-red-700"
                          >
                            Delete
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>

                    <div
                      className={`h-3 w-3 rounded-full ${
                        meter.status === "Active"
                          ? "bg-green-400 shadow-[0_0_15px_#4ade80]"
                          : "bg-red-500 shadow-[0_0_15px_#ef4444]"
                      }`}
                    />

                    <span
                      className={`text-xs font-semibold ${
                        meter.status === "Active"
                          ? "text-green-400"
                          : "text-red-400"
                      }`}
                    >
                      {meter.status.toUpperCase()}
                    </span>
                  </div>
                </div>

                {/* Location */}
                <div className="mb-4 text-sm text-gray-400">
                  📍 {meter.location}
                </div>

                {/* Stats */}
                <div className="mb-4 grid grid-cols-2 gap-3">
                  <div className="rounded-lg bg-black/30 p-3 text-center">
                    <p className="text-xs text-gray-400">Devices</p>
                    <p className="text-xl font-bold text-blue-400">
                      {meter.sensors?.length || 0}
                    </p>
                  </div>

                  <div className="rounded-lg bg-black/30 p-3 text-center">
                    <p className="text-xs text-gray-400">Converters</p>
                    <p className="text-xl font-bold text-yellow-400">
                      {meter.mediaConverters?.length || 0}
                    </p>
                  </div>
                </div>

                <div className="mb-4 rounded-xl border border-[#333] bg-black/20 p-4">
                  <h4 className="mb-3 text-xs font-semibold tracking-[0.2em] text-cyan-400">
                    MEDIA CONVERTERS
                  </h4>

                  <div className="space-y-2">
                    {meter.mediaConverters?.map((mc) => {
                      const healthy =
                        mc.fx && mc.tx && mc.link && mc.pwr && mc.act && mc.fdx;

                      return (
                        <div
                          key={mc.mediaConverterId}
                          className="flex items-center justify-between rounded-lg border border-[#333] bg-[#111]/50 px-3 py-2"
                        >
                          <span className="font-medium text-white">
                            {mc.mediaConverterId}
                          </span>

                          <div className="flex items-center gap-2">
                            <div
                              className={`h-2.5 w-2.5 rounded-full ${
                                healthy
                                  ? "bg-green-400 shadow-[0_0_10px_#4ade80]"
                                  : "bg-red-500 shadow-[0_0_10px_#ef4444]"
                              }`}
                            />

                            <span
                              className={`text-xs font-medium ${
                                healthy ? "text-green-400" : "text-red-400"
                              }`}
                            >
                              {healthy ? "ONLINE" : "FAULT"}
                            </span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Fault Panel */}

                <div className="mt-4 rounded-xl border border-[#333] bg-black/20 p-4">
                  <div className="mb-3 flex items-center justify-between">
                    <h4 className="text-xs font-semibold tracking-[0.2em] text-red-400">
                      ACTIVE FAULTS
                    </h4>

                    <span className="text-[10px] text-gray-500">
                      {faults.length} ISSUE(S)
                    </span>
                  </div>

                  {faults.length > 0 ? (
                    <div className="space-y-2">
                      {faults.map((fault) => (
                        <div
                          key={fault}
                          className="
            flex items-center gap-3
            rounded-lg
            border border-red-500/20
            bg-red-500/10
            px-3 py-2
          "
                        >
                          <div className="h-2 w-2 animate-pulse rounded-full bg-red-500" />

                          <span className="text-sm text-red-300">{fault}</span>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div
                      className="
        flex items-center gap-3
        rounded-lg
        border border-green-500/20
        bg-green-500/10
        px-3 py-3
      "
                    >
                      <div className="h-2 w-2 rounded-full bg-green-400" />

                      <span className="text-sm text-green-300">
                        No active faults detected
                      </span>
                    </div>
                  )}
                </div>
              </div>
            );
          })}

          {filteredMeters.length === 0 && (
            <div className="rounded-xl border border-[#333] bg-[#222] p-8 text-center">
              <Cpu className="mx-auto mb-3 h-10 w-10 text-gray-500" />
              <h3 className="text-lg font-medium text-white">
                No Smart Meters Found
              </h3>
              <p className="mt-2 text-sm text-gray-400">
                Add a Smart Meter to start monitoring media converters.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
